CREATE OR REPLACE FUNCTION public.initialize_governance_city(_city text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.governance_settings; m public.municipal_mandates; r record; base_seats integer; extras integer; allocated integer; BEGIN
PERFORM pg_advisory_xact_lock(hashtextextended('civic:'||_city,0)); SELECT * INTO s FROM public.governance_settings WHERE id=1; IF NOT FOUND THEN RAISE EXCEPTION 'Configuration municipale indisponible'; END IF;
INSERT INTO public.city_indicators(city_id,indicator,value,baseline) SELECT _city,x,55+mod(abs(hashtext(_city||x)::bigint),15),55+mod(abs(hashtext(_city||x)::bigint),15) FROM unnest(ARRAY['housing','employment','transport','environment','safety','services','commerce','culture','satisfaction']) x ON CONFLICT DO NOTHING;
INSERT INTO public.municipal_treasuries(city_id,balance,reserve) VALUES(_city,s.initial_budget,s.reserve) ON CONFLICT DO NOTHING;
FOR m IN SELECT * FROM public.municipal_mandates WHERE city_id=_city AND governance_initialized_at IS NULL ORDER BY starts_at,id FOR UPDATE LOOP
UPDATE public.municipal_mandates SET opening_indicators=(SELECT jsonb_object_agg(indicator,value) FROM public.city_indicators WHERE city_id=_city),opening_politics=COALESCE((SELECT jsonb_build_object('reputation',ps.reputation,'influence',ps.influence) FROM public.political_stats ps JOIN public.candidacies ca ON ca.character_id=ps.character_id WHERE ca.id=m.candidacy_id),'{"reputation":0,"influence":0}'),governance_initialized_at=public.game_now() WHERE id=m.id;
base_seats:=s.council_seats/2+1; extras:=s.council_seats-base_seats; allocated:=0;
FOR r IN SELECT ca.*,er.rank,er.votes,COALESCE(o.name,'Indépendants — '||ca.display_name) group_name,COALESCE(pp.ideology,'{}') group_ideology FROM public.election_results er JOIN public.candidacies ca ON ca.id=er.candidacy_id LEFT JOIN public.organizations o ON o.id=ca.organization_id LEFT JOIN public.political_profiles pp ON pp.organization_id=o.id WHERE er.election_id=m.election_id ORDER BY er.votes DESC,er.candidacy_id LOOP
INSERT INTO public.municipal_council_groups(mandate_id,organization_id,candidate_id,name,seats,majority,ideology,leader_id,base_support) VALUES(m.id,r.organization_id,r.id,r.group_name,CASE WHEN r.id=m.candidacy_id THEN base_seats ELSE 0 END,r.id=m.candidacy_id,r.group_ideology,COALESCE(r.npc_id,(SELECT n.id FROM public.social_npcs n WHERE n.city_id=_city AND n.organization_id=r.organization_id ORDER BY n.id LIMIT 1)),CASE WHEN r.id=m.candidacy_id THEN 55 ELSE 30 END) ON CONFLICT DO NOTHING;
END LOOP;
IF NOT EXISTS(SELECT 1 FROM public.municipal_council_groups WHERE mandate_id=m.id) THEN RAISE EXCEPTION 'Résultats électoraux requis pour le conseil'; END IF;
FOR r IN SELECT ca.id,er.votes,er.rank FROM public.election_results er JOIN public.candidacies ca ON ca.id=er.candidacy_id WHERE er.election_id=m.election_id ORDER BY er.votes DESC,er.candidacy_id LOOP
UPDATE public.municipal_council_groups SET seats=seats+floor(extras*r.votes::numeric/GREATEST(1,(SELECT sum(votes) FROM public.election_results WHERE election_id=m.election_id)))::integer WHERE mandate_id=m.id AND candidate_id=r.id; END LOOP;
allocated:=s.council_seats-(SELECT sum(seats) FROM public.municipal_council_groups WHERE mandate_id=m.id);
FOR r IN SELECT g.id FROM public.municipal_council_groups g JOIN public.election_results er ON er.candidacy_id=g.candidate_id AND er.election_id=m.election_id WHERE g.mandate_id=m.id ORDER BY (extras*er.votes::numeric/GREATEST(1,(SELECT sum(votes) FROM public.election_results WHERE election_id=m.election_id)))-floor(extras*er.votes::numeric/GREATEST(1,(SELECT sum(votes) FROM public.election_results WHERE election_id=m.election_id))) DESC,g.candidate_id LIMIT allocated LOOP UPDATE public.municipal_council_groups SET seats=seats+1 WHERE id=r.id; END LOOP;
END LOOP;
END $$;
REVOKE ALL ON FUNCTION public.initialize_governance_city(text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.initialize_governance_city(text) TO service_role;
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.refresh_civic_city(text)'::regprocedure) INTO def;
def:=replace(def,'WHERE city_id=_city AND status<>''resolved''','WHERE city_id=_city AND NOT governance_managed AND status<>''resolved''');
def:=replace(def,'WHERE city_id=_city AND status=''open'' AND ends_at<=public.game_now()','WHERE city_id=_city AND NOT advisory AND status=''open'' AND ends_at<=public.game_now()'); EXECUTE def; END $$;
CREATE OR REPLACE FUNCTION public.guard_civic_decision_deadline() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.mandate_id IS NOT NULL AND NEW.funded_at IS NULL THEN NEW.status:='planned'; NEW.applied_at:=NULL; ELSIF NEW.decided_at>public.game_now() AND NEW.status='applied' THEN NEW.status:='planned'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.apply_civic_decision() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF NEW.mandate_id IS NOT NULL AND NEW.funded_at IS NULL THEN NEW.status:='planned'; RETURN NEW; END IF;
IF NEW.status='applied' AND NEW.applied_at IS NULL THEN
IF NEW.consequences ? 'project' THEN UPDATE public.locations SET civic_project=NEW.consequences->>'project' WHERE id=NEW.location_id AND city_id=NEW.city_id; END IF;
IF NEW.consequences ? 'state' THEN UPDATE public.locations SET civic_state=NEW.consequences->>'state' WHERE id=NEW.location_id AND city_id=NEW.city_id; END IF;
NEW.applied_at:=public.game_now(); NEW.news_id:=public.civic_news('decision:'||NEW.id,NEW.title,NEW.description,NEW.city_id,NEW.location_id); END IF; RETURN NEW; END $$;
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.civic_actor()'::regprocedure) INTO def; def:=replace(def,'AND applied_at IS NULL','AND applied_at IS NULL AND (mandate_id IS NULL OR funded_at IS NOT NULL)'); EXECUTE def; END $$;
CREATE OR REPLACE FUNCTION public.governance_news(_decision uuid,_key text,_title text,_body text,_at timestamptz,_kind text DEFAULT 'announcement') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.public_decisions; eid uuid;nid uuid; BEGIN SELECT * INTO d FROM public.public_decisions WHERE id=_decision; IF NOT FOUND THEN RETURN NULL; END IF;
INSERT INTO public.events(event_key,title,description,news_body,city_id,starts_at,scope,category,importance,source_id,location_id,target_kind) VALUES('governance:'||d.id||':'||_key,_title,_body,_body,d.city_id,_at,'local','Politique',80,'civitas-matin',d.location_id,'city') ON CONFLICT(event_key) DO NOTHING;
SELECT id INTO eid FROM public.events WHERE event_key='governance:'||d.id||':'||_key; nid:=public.publish_world_event(eid);
UPDATE public.news SET related_entities=related_entities||jsonb_build_object('governance',true,'decision_id',d.id) WHERE id=nid;
INSERT INTO public.governance_reactions(city_id,decision_id,reaction_key,kind,title,description,occurred_at,news_id) VALUES(d.city_id,d.id,d.id||':'||_key,_kind,_title,_body,_at,nid) ON CONFLICT DO NOTHING; RETURN nid; END $$;
REVOKE ALL ON FUNCTION public.governance_news(uuid,text,text,text,timestamptz,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.governance_news(uuid,text,text,text,timestamptz,text) TO service_role;
CREATE OR REPLACE FUNCTION public.governance_owner(_mandate uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; c public.characters;m public.municipal_mandates; BEGIN cid:=public.prepare_daily_life(); SELECT * INTO c FROM public.characters WHERE id=cid; SELECT * INTO m FROM public.municipal_mandates WHERE id=_mandate; IF NOT FOUND OR m.city_id<>c.city_id OR m.status<>'active' OR public.game_now()<m.starts_at OR public.game_now()>=m.ends_at OR NOT EXISTS(SELECT 1 FROM public.candidacies WHERE id=m.candidacy_id AND character_id=cid) OR EXISTS(SELECT 1 FROM public.municipal_mandates other WHERE other.city_id=m.city_id AND other.starts_at>m.starts_at AND other.starts_at<=public.game_now()) THEN RAISE EXCEPTION 'Mandat actif requis dans votre ville'; END IF;
PERFORM pg_advisory_xact_lock(hashtextextended('civic:'||m.city_id,0)); PERFORM public.initialize_governance_city(m.city_id); RETURN cid; END $$;
REVOKE ALL ON FUNCTION public.governance_owner(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.governance_owner(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.set_mandate_priorities(_mandate_id uuid,_priorities text[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; cap integer;city text; BEGIN cid:=public.governance_owner(_mandate_id); SELECT max_priorities INTO cap FROM public.governance_settings WHERE id=1; IF _priorities IS NULL OR cardinality(_priorities)>cap OR cardinality(_priorities)<>(SELECT count(DISTINCT p) FROM unnest(_priorities) p) OR EXISTS(SELECT 1 FROM unnest(_priorities) p WHERE p IS NULL OR p NOT IN('housing','employment','transport','environment','safety','services','commerce','culture')) THEN RAISE EXCEPTION 'Trois priorités distinctes au maximum'; END IF; UPDATE public.municipal_mandates SET priorities=_priorities WHERE id=_mandate_id; END $$;
REVOKE ALL ON FUNCTION public.set_mandate_priorities(uuid,text[]) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.set_mandate_priorities(uuid,text[]) TO authenticated;
CREATE OR REPLACE FUNCTION public.create_municipal_dossier(_mandate_id uuid,_rule_id text,_issue_id uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid;m public.municipal_mandates;r public.governance_rules;l public.locations;inst uuid;did uuid;g public.municipal_council_groups;sup integer; BEGIN cid:=public.governance_owner(_mandate_id); SELECT * INTO m FROM public.municipal_mandates WHERE id=_mandate_id; SELECT * INTO r FROM public.governance_rules WHERE id=_rule_id; IF NOT FOUND OR NOT r.indicator=ANY(m.priorities) THEN RAISE EXCEPTION 'Choisissez une priorité du mandat correspondant à ce dossier'; END IF;
IF EXISTS(SELECT 1 FROM public.public_decisions WHERE mandate_id=m.id AND governance_rule_id=r.id AND workflow NOT IN('abandoned','rejected')) THEN RAISE EXCEPTION 'Ce dossier existe déjà pour ce mandat'; END IF;
SELECT * INTO l FROM public.locations WHERE city_id=m.city_id AND kind=r.location_kind AND accessible AND district_id IS NOT NULL ORDER BY id LIMIT 1; IF NOT FOUND THEN RAISE EXCEPTION 'Lieu municipal indisponible'; END IF;
SELECT id INTO inst FROM public.institutions WHERE city_id=m.city_id AND type='Mairie' ORDER BY id LIMIT 1;
IF _issue_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.public_issues WHERE id=_issue_id AND city_id=m.city_id AND status<>'resolved') THEN RAISE EXCEPTION 'Problème inaccessible'; END IF;
IF _issue_id IS NOT NULL THEN SELECT ll.* INTO l FROM public.locations ll JOIN public.public_issues pi ON pi.location_id=ll.id WHERE pi.id=_issue_id; UPDATE public.public_issues SET governance_managed=true,indicator=r.indicator WHERE id=_issue_id; END IF;
INSERT INTO public.public_decisions(decision_key,institution_id,city_id,district_id,location_id,issue_id,title,description,status,mandate_id,governance_rule_id,workflow,objective,cost,duration_days,impact_expected,rule_snapshot) VALUES('governance:'||gen_random_uuid(),inst,m.city_id,l.district_id,l.id,_issue_id,r.title,r.objective,'planned',m.id,r.id,'idea',r.objective,r.cost,r.duration_days,r.completion||r.delayed,to_jsonb(r)) RETURNING id INTO did;
FOR g IN SELECT * FROM public.municipal_council_groups WHERE mandate_id=m.id LOOP sup:=LEAST(100,GREATEST(0,g.base_support+round((50-abs(COALESCE((g.ideology->>r.axis)::integer,50)-r.target))/2.0)::integer)); INSERT INTO public.governance_positions VALUES(did,g.id,sup,false,CASE WHEN sup>=50 THEN 'Soutien' WHEN sup>=40 THEN 'Demande de modification' ELSE 'Opposition' END); END LOOP;
RETURN did; END $$;
REVOKE ALL ON FUNCTION public.create_municipal_dossier(uuid,text,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.create_municipal_dossier(uuid,text,uuid) TO authenticated;